-- 533: Original BrillaPrep flashcards, batch flashcards-beta-002, part 2 of 5.
-- Curriculum-aligned revision content; not official WAEC, NaCCA or NSMQ material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_statistics_05', 'deck_sys_topic_statistics', 'Write the formula for the variance of a population, and define standard deviation.', 'Variance σ² = Σ(x − μ)²/n, the mean of the squared deviations from the mean μ. The standard deviation σ is the positive square root of the variance.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_statistics_06', 'deck_sys_topic_statistics', 'State the addition rule of probability for two events A and B.', 'P(A ∪ B) = P(A) + P(B) − P(A ∩ B). If A and B are mutually exclusive, P(A ∩ B) = 0 and the rule reduces to P(A) + P(B).', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_statistics_07', 'deck_sys_topic_statistics', 'State the multiplication rule for two independent events.', 'If A and B are independent, P(A ∩ B) = P(A) × P(B) — the probability of both occurring is the product of their separate probabilities.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_statistics_08', 'deck_sys_topic_statistics', 'Define the conditional probability P(A|B).', 'P(A|B) = P(A ∩ B)/P(B), provided P(B) > 0: the probability of A given that B has already occurred.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_statistics_09', 'deck_sys_topic_statistics', 'Within what range must every probability lie, and what do the endpoints mean?', '0 ≤ P(E) ≤ 1 for every event E. P(E) = 0 means the event is impossible; P(E) = 1 means it is certain.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_statistics_10', 'deck_sys_topic_statistics', 'A fair die is thrown once. What is the probability of obtaining a score greater than 4?', 'The favourable outcomes are 5 and 6, so P = 2/6 = 1/3.', NULL, 'Count the favourable faces out of six equally likely faces.', 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_kinematics_01', 'deck_sys_topic_kinematics', 'Distinguish between distance and displacement.', 'Distance is the total length of the path travelled (a scalar); displacement is the straight-line change in position from start to finish, with direction (a vector).', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_kinematics_02', 'deck_sys_topic_kinematics', 'Define acceleration and state its SI unit.', 'Acceleration is the rate of change of velocity, a = Δv/Δt; its SI unit is the metre per second squared (m/s²).', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_kinematics_03', 'deck_sys_topic_kinematics', 'What does the area under a velocity–time graph represent?', 'The displacement of the body over the time interval considered (area above the time axis is positive displacement, below it negative).', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_kinematics_04', 'deck_sys_topic_kinematics', 'What does the gradient of a displacement–time graph give?', 'The velocity of the body; the gradient at a point gives the instantaneous velocity, ds/dt.', NULL, 'Gradient = rate of change.', 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_kinematics_05', 'deck_sys_topic_kinematics', 'What is free fall?', 'Motion under the influence of gravity alone, with negligible air resistance; near the Earth’s surface the acceleration is g ≈ 9.81 m/s² directed downwards.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_kinematics_06', 'deck_sys_topic_kinematics', 'Write the kinematic equation that gives displacement from the average of the initial and final velocities.', 's = ½(u + v)t, valid for uniform (constant) acceleration: displacement equals average velocity multiplied by time.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_kinematics_07', 'deck_sys_topic_kinematics', 'What is the acceleration of a body moving with constant velocity?', 'Zero — acceleration is the rate of change of velocity, and a constant velocity (including rest) does not change.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_kinematics_08', 'deck_sys_topic_kinematics', 'Write the formula for the horizontal range of a projectile launched with speed u at angle θ to the horizontal.', 'R = u² sin 2θ / g. For a given launch speed the range is greatest when θ = 45°, since sin 2θ is then 1.', NULL, NULL, 4);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_kinematics_09', 'deck_sys_topic_kinematics', 'A car starts from rest and accelerates uniformly at 2 m/s² for 5 s. What is its final velocity?', 'v = u + at = 0 + (2)(5) = 10 m/s.', NULL, '“Starts from rest” means u = 0.', 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_kinematics_10', 'deck_sys_topic_kinematics', 'Define instantaneous velocity.', 'The velocity of a body at a particular instant: the limiting value of the average velocity as the time interval shrinks to zero, v = ds/dt.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_waves_01', 'deck_sys_topic_waves', 'What is a wave?', 'A disturbance that transfers energy from one point to another without any net transfer of matter.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_waves_02', 'deck_sys_topic_waves', 'Distinguish between transverse and longitudinal waves, giving one example of each.', 'In transverse waves the oscillations are perpendicular to the direction of travel (e.g. light, water ripples); in longitudinal waves they are parallel to it (e.g. sound in air).', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_waves_03', 'deck_sys_topic_waves', 'How are the period T and the frequency f of a wave related?', 'T = 1/f: the period is the reciprocal of the frequency. T is measured in seconds and f in hertz (Hz).', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_waves_04', 'deck_sys_topic_waves', 'State the law of reflection.', 'The angle of incidence equals the angle of reflection, both measured from the normal at the point of incidence, with the incident ray, reflected ray and normal all in one plane.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_waves_05', 'deck_sys_topic_waves', 'Define the refractive index of a medium.', 'n = c/v: the ratio of the speed of light in a vacuum to its speed in the medium. Equivalently, n = sin i / sin r for light entering the medium from air.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_waves_06', 'deck_sys_topic_waves', 'State Snell’s law of refraction.', 'n₁ sin θ₁ = n₂ sin θ₂, where θ₁ and θ₂ are the angles the ray makes with the normal in media of refractive indices n₁ and n₂.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_waves_07', 'deck_sys_topic_waves', 'What is diffraction, and when is it most noticeable?', 'The spreading of waves as they pass through a gap or around an obstacle; it is greatest when the gap or obstacle is comparable in size to the wavelength.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_waves_08', 'deck_sys_topic_waves', 'What is total internal reflection, and under what conditions does it occur?', 'The complete reflection of light back into a denser medium at a boundary with a less dense medium; it occurs only when light travels from the optically denser medium and the angle of incidence exceeds the critical angle.', NULL, NULL, 3);
